1	/**
2	 * @module core/errors/userErrors
3	 *
4	 * What users see when something goes wrong (A4, UX-first): a warm, plain
5	 * message, a hint about what to do next, and whether retrying can help.
6	 * Technical detail never appears here — it goes to the server log
7	 * (`ErrorName || message || fn || emoji`) and the `events` table.
8	 * ALL user-facing error copy lives in this one file.
9	 */
10	import { ZodError } from "zod";
11	import { AgentInputError } from "./agentInputError";
12	import { BoundaryError } from "./boundaryError";
13	
14	/** Error codes the API can return. */
15	export const USER_ERROR_CODES = ["invalid_request", "unauthorized", "too_many_requests", "daily_limit", "no_data", "agent_failed", "internal_error"] as const;
16	
17	/** One of the API error codes. */
18	export type UserErrorCode = (typeof USER_ERROR_CODES)[number];
19	
20	/** The error body the browser receives: `{ error: UserError }` (minus `status`). */
21	export interface UserError {
22	  code: UserErrorCode;
23	  /** Friendly, plain-language message. */
24	  message: string;
25	  /** What the user can do next. */
26	  hint: string;
27	  /** Whether trying again may work (the UI shows a "Try again" button). */
28	  retryable: boolean;
29	  /** HTTP status code. */
30	  status: number;
31	}
32	
33	/** The copy for each error code. */
34	export const USER_ERRORS: Record<UserErrorCode, Omit<UserError, "code">> = {
35	  invalid_request: {
36	    status: 400,
37	    message: "I couldn't quite read that question.",
38	    hint: "Try asking it in a sentence or two — for example: “Which hubs are most exposed to flooding?”",
39	    retryable: false,
40	  },
41	  unauthorized: {
42	    status: 401,
43	    message: "This address is only for Sneakoscope's nightly data job.",
44	    hint: "To use Sneakoscope, open the home page and ask a question. 🐱",
45	    retryable: false,
46	  },
47	  too_many_requests: {
48	    status: 429,
49	    message: "You're asking faster than I can keep up. 😸",
50	    hint: "Please take a short break and try again in a few minutes.",
51	    retryable: false,
52	  },
53	  daily_limit: {
54	    status: 429,
55	    message: "Sneakoscope has answered a lot of questions today. 🐱",
56	    hint: "The daily limit resets at midnight UTC. Please come back tomorrow.",
57	    retryable: false,
58	  },
59	  no_data: {
60	    status: 503,
61	    message: "Today's weather data hasn't landed yet. 🐱",
62	    hint: "Scores refresh every night. Please try again in a few minutes.",
63	    retryable: true,
64	  },
65	  agent_failed: {
66	    status: 502,
67	    message: "I couldn't put together an answer I can stand behind this time.",
68	    hint: "I'd rather say so than guess. Try asking again — naming one or two hubs or a single hazard usually helps.",
69	    retryable: true,
70	  },
71	  internal_error: {
72	    status: 500,
73	    message: "Something went wrong on our side. 😿",
74	    hint: "It's not you — please try again in a moment. If it keeps happening, let the team know.",
75	    retryable: true,
76	  },
77	};
78	
79	/**
80	 * Builds the user-facing error for a code (optionally with a more specific message).
81	 * @param code - the error code.
82	 * @param message - a specific friendly message to use instead of the default.
83	 * @returns the user error.
84	 */
85	export function userError(code: UserErrorCode, message?: string): UserError {
86	  return { code, ...USER_ERRORS[code], ...(message ? { message } : {}) };
87	}
88	
89	/**
90	 * Classifies any thrown value into a friendly user error.
91	 * @param error - whatever was thrown.
92	 * @returns the user error (never contains internal details).
93	 */
94	export function toUserError(error: unknown): UserError {
95	  if (error instanceof AgentInputError) return userError("invalid_request", error.message);
96	  if (error instanceof ZodError) return userError("invalid_request");
97	  if (error instanceof BoundaryError) {
98	    if (error.name === "NoDataError") return userError("no_data");
99	    if (error.boundary === "llm") return userError("agent_failed");
100	  }
101	  return userError("internal_error");
102	}
103	
104	/** Shown when a streamed answer stops before the validated answer arrives (e.g. the connection dropped). */
105	export const STREAM_INTERRUPTED: Omit<UserError, "status"> = {
106	  code: "internal_error",
107	  message: "The answer stopped before it finished.",
108	  hint: "Your connection may have dropped — please try again.",
109	  retryable: true,
110	};
