1	/**
2	 * @module core/agent/answerQuestion
3	 *
4	 * The ONE entry point for answering a chat message — used by `npm run ask`
5	 * and (Step 5) `POST /api/chat`. Loads context + memory, runs the out-of-scope
6	 * guard (Step 11), runs the agent, saves the turn, and logs events under one
7	 * correlation id per turn.
8	 */
9	import { randomUUID } from "node:crypto";
10	import type { ModelMessage } from "ai";
11	import type { NewEvent } from "../db/eventsRepository";
12	import { describeUnknownError } from "../errors/boundaryError";
13	import type { UnitSystem } from "../utils/units";
14	import type { FinalAnswer } from "./answerSchema";
15	import { guardDeclineAnswer, recentTurnsFromHistory, type GuardInput, type GuardVerdict } from "../guard/jevGuard";
16	import { AGENT_LIMITS, HISTORY_TURNS } from "./config";
17	import type { AgentContext } from "./context";
18	import type { AgentModel } from "./model";
19	import { runAgent, type AgentCallbacks, type AgentResult } from "./runAgent";
20	
21	/** A chat message from the user. */
22	export interface QuestionInput {
23	  /** Existing session id from the browser, or null to start a new conversation. */
24	  sessionId: string | null;
25	  message: string;
26	  units: UnitSystem;
27	}
28	
29	/** Everything answerQuestion needs (injectable for tests). */
30	export interface AnswerQuestionDeps {
31	  agentModel: AgentModel;
32	  loadContext: (options: { today: string; units: UnitSystem }) => Promise<AgentContext>;
33	  ensureSession: (sessionId: string | null) => Promise<string>;
34	  loadHistory: (sessionId: string, turns: number) => Promise<ModelMessage[]>;
35	  saveTurn: (sessionId: string, messages: ModelMessage[], answer: FinalAnswer, model: string) => Promise<void>;
36	  recordEvent: (event: NewEvent) => Promise<boolean>;
37	  /** The out-of-scope guard (D118). Must not throw: it fails open itself. */
38	  guard: (input: GuardInput) => Promise<GuardVerdict>;
39	  /** Today `YYYY-MM-DD` (UTC). */
40	  today: () => string;
41	}
42	
43	/** The result returned to the caller. */
44	export interface QuestionResult {
45	  sessionId: string;
46	  answer: FinalAnswer;
47	  usage: AgentResult["usage"];
48	}
49	
50	/**
51	 * Answers one chat message end to end.
52	 * @param input - session, message and unit system.
53	 * @param deps - model, data access and logging.
54	 * @param callbacks - live progress hooks, plus `onSession` (called as soon as the session id is known).
55	 * @returns the session id, the checked answer and token usage.
56	 * @throws AgentInputError / BoundaryError — also logged as an `agent.failed` event.
57	 */
58	export async function answerQuestion(
59	  input: QuestionInput,
60	  deps: AnswerQuestionDeps,
61	  callbacks: AgentCallbacks & { onSession?: (sessionId: string) => void } = {},
62	): Promise<QuestionResult> {
63	  const correlationId = randomUUID();
64	  const sessionId = await deps.ensureSession(input.sessionId);
65	  callbacks.onSession?.(sessionId);
66	  try {
67	    const [context, history] = await Promise.all([
68	      deps.loadContext({ today: deps.today(), units: input.units }),
69	      deps.loadHistory(sessionId, HISTORY_TURNS),
70	    ]);
71	
72	    // The guard (D118) runs before the paid agent. Empty or over-long messages skip it:
73	    // runAgent rejects those with its own friendly message.
74	    const message = input.message.trim();
75	    if (message.length > 0 && message.length <= AGENT_LIMITS.maxUserMessageChars) {
76	      const verdict = await deps.guard({
77	        message,
78	        history: recentTurnsFromHistory(history),
79	        hubNames: context.hubs.map((hub) => `${hub.name}, ${hub.state}`),
80	      });
81	      await deps.recordEvent({
82	        eventType: "guard.decision",
83	        source: "guard",
84	        level: verdict.decision === "decline" || verdict.failedOpen ? "warn" : "info",
85	        correlationId,
86	        sessionId,
87	        message: verdict.failedOpen ? `failed open: ${verdict.error}` : `${verdict.decision}${verdict.reason ? ` (${verdict.reason})` : ""}`,
88	        payload: {
89	          decision: verdict.decision,
90	          reason: verdict.reason,
91	          mode: verdict.mode,
92	          inScope: verdict.scores?.inScope ?? null,
93	          manipulation: verdict.scores?.manipulation ?? null,
94	          failedOpen: verdict.failedOpen,
95	          ms: verdict.ms,
96	          model: verdict.model,
97	        },
98	      });
99	      if (verdict.decision === "decline" && verdict.reason) {
100	        const answer = guardDeclineAnswer(verdict.reason, context.hubs.length);
101	        await deps.saveTurn(sessionId, [{ role: "user", content: message }, { role: "assistant", content: answer.answer }], answer, verdict.model);
102	        return { sessionId, answer, usage: { inputTokens: 0, outputTokens: 0 } };
103	      }
104	    }
105	
106	    const result = await runAgent(
107	      { message: input.message, history },
108	      { model: deps.agentModel.model, modelId: deps.agentModel.modelId, context },
109	      {
110	        ...callbacks,
111	        onRetry: (problems) => {
112	          void deps.recordEvent({
113	            eventType: "agent.retry",
114	            source: "agent",
115	            level: "warn",
116	            correlationId,
117	            sessionId,
118	            message: problems.join(" | "),
119	            payload: { problems },
120	          });
121	          callbacks.onRetry?.(problems);
122	        },
123	      },
124	    );
125	    await deps.saveTurn(sessionId, result.newMessages, result.answer, deps.agentModel.modelId);
126	    await deps.recordEvent({
127	      eventType: "agent.answered",
128	      source: "agent",
129	      level: result.answer.meta.warnings.length > 0 ? "warn" : "info",
130	      correlationId,
131	      sessionId,
132	      message: `${result.answer.meta.toolCalls.length} tool calls, confidence ${result.answer.confidence ?? "n/a"}`,
133	      payload: {
134	        model: deps.agentModel.modelId,
135	        tools: result.answer.meta.toolCalls.map((c) => c.tool),
136	        outOfScope: result.answer.outOfScope,
137	        retried: result.answer.meta.retried,
138	        confidence: result.answer.confidence,
139	        confidenceOverridden: result.answer.meta.confidenceOverridden,
140	        premiseHolds: result.answer.premiseCheck?.holds ?? null,
141	        warnings: result.answer.meta.warnings,
142	        inputTokens: result.usage.inputTokens,
143	        outputTokens: result.usage.outputTokens,
144	      },
145	    });
146	    return { sessionId, answer: result.answer, usage: result.usage };
147	  } catch (error) {
148	    await deps.recordEvent({
149	      eventType: "agent.failed",
150	      source: "agent",
151	      level: "error",
152	      correlationId,
153	      sessionId,
154	      message: describeUnknownError(error),
155	      payload: { model: deps.agentModel.modelId },
156	    });
157	    throw error;
158	  }
159	}
