1	/**
2	 * @module core/agent/runAgent
3	 *
4	 * One agent turn: the model picks tools, the tools compute everything, the
5	 * model writes a structured answer, and CODE checks and completes it.
6	 *
7	 *   streamText(tools + Output.object(llmAnswerSchema))
8	 *     → stream answer text as it's written (onAnswerDelta)
9	 *     → finalizeAnswer (numbers/hubs trace to tools; code sets confidence,
10	 *       premise verdict, caveats, disclaimer)
11	 *     → invalid? send the problems back and retry ONCE → still invalid? clear error.
12	 */
13	import {
14	  isStepCount,
15	  NoObjectGeneratedError,
16	  NoOutputGeneratedError,
17	  Output,
18	  streamText,
19	  type LanguageModel,
20	  type ModelMessage,
21	} from "ai";
22	import { AgentInputError } from "../errors/agentInputError";
23	import { BoundaryError, describeUnknownError } from "../errors/boundaryError";
24	
25	export { AgentInputError };
26	import { buildSystemPrompt } from "./systemPrompt";
27	import { llmAnswerSchema, type FinalAnswer, type LlmAnswer } from "./answerSchema";
28	import { AGENT_LIMITS, RETRY_FEEDBACK_PREFIX } from "./config";
29	import type { AgentContext } from "./context";
30	import { finalizeAnswer } from "./finalizeAnswer";
31	import { ToolLedger } from "./ledger";
32	import { buildTools } from "./tools";
33	import type { ToolCallbacks } from "./tools/shared";
34	
35	/** The user's question plus the conversation so far. */
36	export interface AgentRequest {
37	  message: string;
38	  /** Earlier turns (already trimmed to the history window, G7). */
39	  history: ModelMessage[];
40	}
41	
42	/** What the agent needs to run. */
43	export interface AgentDeps {
44	  model: LanguageModel;
45	  modelId: string;
46	  context: AgentContext;
47	}
48	
49	/** Live progress hooks (the API streams these to the browser). */
50	export interface AgentCallbacks extends ToolCallbacks {
51	  /** New characters of the answer text as the model writes it. */
52	  onAnswerDelta?: (delta: string) => void;
53	  /** The first answer failed validation; a retry is starting. */
54	  onRetry?: (problems: string[]) => void;
55	}
56	
57	/** Result of one turn. */
58	export interface AgentResult {
59	  answer: FinalAnswer;
60	  /** Messages to append to the conversation history (user message, tool calls/results, answers). */
61	  newMessages: ModelMessage[];
62	  usage: { inputTokens: number; outputTokens: number };
63	}
64	
65	
66	/**
67	 * Runs one model attempt and streams the answer text.
68	 * @returns the raw structured answer (or the reason it's missing) and the response messages.
69	 */
70	async function attempt(
71	  messages: ModelMessage[],
72	  system: string,
73	  deps: AgentDeps,
74	  tools: ReturnType<typeof buildTools>,
75	  callbacks: AgentCallbacks,
76	): Promise<{ raw: LlmAnswer | null; problem: string | null; responseMessages: ModelMessage[]; usage: AgentResult["usage"] }> {
77	  let streamError: unknown = null;
78	  const result = streamText({
79	    model: deps.model,
80	    system,
81	    messages,
82	    tools,
83	    output: Output.object({ schema: llmAnswerSchema }),
84	    stopWhen: isStepCount(AGENT_LIMITS.maxToolSteps + 1),
85	    timeout: AGENT_LIMITS.timeouts,
86	    maxOutputTokens: AGENT_LIMITS.maxOutputTokens,
87	    maxRetries: 1,
88	    onError: ({ error }) => {
89	      streamError = error;
90	    },
91	  });
92	
93	  /**
94	   * Wraps a failed model call (timeout, network, provider error) in the 🦉 boundary format.
95	   * A step timeout makes the partial-output stream itself throw (D108), so the loop below is guarded too.
96	   */
97	  const callFailed = (cause: unknown) =>
98	    new BoundaryError({
99	      name: "LlmCallError",
100	      message: `The model call failed: ${describeUnknownError(cause)}`,
101	      functionName: "runAgent",
102	      boundary: "llm",
103	      cause,
104	    });
105	
106	  let sent = 0;
107	  try {
108	    for await (const partial of result.partialOutputStream) {
109	      const text = (partial as Partial<LlmAnswer> | undefined)?.answer;
110	      if (typeof text === "string" && text.length > sent) {
111	        callbacks.onAnswerDelta?.(text.slice(sent));
112	        sent = text.length;
113	      }
114	    }
115	  } catch (error) {
116	    throw callFailed(streamError ?? error);
117	  }
118	
119	  let raw: LlmAnswer | null = null;
120	  let problem: string | null = null;
121	  try {
122	    raw = await result.output;
123	  } catch (error) {
124	    if (streamError) throw callFailed(streamError);
125	    if (NoObjectGeneratedError.isInstance(error) || NoOutputGeneratedError.isInstance(error)) {
126	      problem = `Your final answer did not match the required JSON schema (${describeUnknownError(error)}).`;
127	    } else throw callFailed(error);
128	  }
129	  const usage = await result.totalUsage;
130	  return {
131	    raw,
132	    problem,
133	    responseMessages: (await result.responseMessages) as ModelMessage[],
134	    usage: { inputTokens: usage.inputTokens ?? 0, outputTokens: usage.outputTokens ?? 0 },
135	  };
136	}
137	
138	/**
139	 * Answers one question.
140	 * @param request - the message and history.
141	 * @param deps - model and per-request context.
142	 * @param callbacks - progress hooks.
143	 * @returns the checked answer, the new history messages and token usage.
144	 * @throws AgentInputError for an invalid question; BoundaryError (llm) when the model fails or keeps producing invalid answers.
145	 */
146	export async function runAgent(request: AgentRequest, deps: AgentDeps, callbacks: AgentCallbacks = {}): Promise<AgentResult> {
147	  const message = request.message.trim();
148	  if (message.length === 0) throw new AgentInputError("Please type a question first — for example: “Why is the Dallas hub risky?”");
149	  if (message.length > AGENT_LIMITS.maxUserMessageChars) {
150	    throw new AgentInputError(`That message is too long for me — please keep it under ${AGENT_LIMITS.maxUserMessageChars.toLocaleString("en-US")} characters.`);
151	  }
152	
153	  const ledger = new ToolLedger();
154	  ledger.seedFromHistory(request.history);
155	  // Facts the system prompt states, so they're known even though no tool returned them: the hub count
156	  // ("36 hubs") and this year and last year ("Today is …"), which rule 14 asks the agent to name (D122).
157	  const year = Number(deps.context.today.slice(0, 4));
158	  ledger.addKnownNumbers([deps.context.hubs.length, year, year - 1]);
159	  const tools = buildTools(deps.context, { ledger, callbacks });
160	  const system = buildSystemPrompt(deps.context);
161	  const newMessages: ModelMessage[] = [{ role: "user", content: message }];
162	  const usage = { inputTokens: 0, outputTokens: 0 };
163	  let problems: string[] = [];
164	
165	  for (let attemptNo = 0; attemptNo <= AGENT_LIMITS.validationRetries; attemptNo++) {
166	    const run = await attempt([...request.history, ...newMessages], system, deps, tools, callbacks);
167	    newMessages.push(...run.responseMessages);
168	    usage.inputTokens += run.usage.inputTokens;
169	    usage.outputTokens += run.usage.outputTokens;
170	
171	    if (run.raw) {
172	      const final = finalizeAnswer(run.raw, {
173	        ledger,
174	        levelsByHub: deps.context.levelsByHub,
175	        model: deps.modelId,
176	        retried: attemptNo > 0,
177	      });
178	      if (final.ok) return { answer: final.answer, newMessages, usage };
179	      problems = final.problems;
180	    } else {
181	      problems = [run.problem ?? "No answer was produced."];
182	    }
183	
184	    if (attemptNo < AGENT_LIMITS.validationRetries) {
185	      callbacks.onRetry?.(problems);
186	      newMessages.push({
187	        role: "user",
188	        content: `${RETRY_FEEDBACK_PREFIX}\n- ${problems.join("\n- ")}\nFix these and answer again. Use the tool results you already have; only call a tool if you truly need data you don't have yet.`,
189	      });
190	    }
191	  }
192	
193	  throw new BoundaryError({
194	    name: "AgentAnswerValidationError",
195	    message: `The answer failed validation twice: ${problems.join(" | ")}`,
196	    functionName: "runAgent",
197	    boundary: "llm",
198	  });
199	}
