4	 * Records every tool result produced while answering one question. The answer
5	 * validator uses it as the ground truth: hubs, numbers, confidences and
6	 * caveats in the final answer must trace back to entries here.
7	 */
8	import type { ModelMessage } from "ai";
9	import { HAZARD_WEIGHTS, OVERALL_MIX, RISK_LEVEL_CUTOFFS, SCORING_WINDOW_DAYS } from "../scoring/config";
10	import { DAY_METRICS } from "../scoring/dayMetrics";
11	import type { Confidence } from "../scoring/types";
12	import type { ToolCallRecord } from "./answerSchema";
13	
14	/** Fields every tool output carries so the ledger can read them uniformly. */
15	export interface ToolOutputBase {
16	  /** Hub ids this result contains data for. */
17	  hubIds: string[];
18	  /** Weakest confidence of the data in this result (null when not applicable, e.g. an error). */
19	  confidence: Confidence | null;
20	  /** Standing caveats that apply to this result (G4). */
21	  caveats: string[];
22	}
23	
24	/**
25	 * Numbers inside text, e.g. "72.4", "-18", "1,826". A minus sign only counts
26	 * when it is NOT right after a digit — in "0-100" the dash is a range, not a sign.
27	 */
28	const NUMBER_IN_TEXT = /(?:(?<![\d.])-)?\d[\d,]*(?:\.\d+)?/g;
29	
30	
31	/**
32	 * Collects every number in a value: numeric fields and numbers written inside strings.
33	 * @param value - any JSON-like value.
34	 * @param into - accumulator.
35	 * @returns the accumulator.
36	 */
37	export function collectNumbers(value: unknown, into: number[] = []): number[] {
38	  if (typeof value === "number" && Number.isFinite(value)) into.push(value);
39	  else if (typeof value === "string") {
40	    for (const match of value.match(NUMBER_IN_TEXT) ?? []) into.push(Number(match.replace(/,/g, "")));
41	  } else if (Array.isArray(value)) value.forEach((item) => collectNumbers(item, into));
42	  else if (value && typeof value === "object") Object.values(value).forEach((item) => collectNumbers(item, into));
43	  return into;
44	}
45	
46	/** Share of each half in a mixed hazard (hazards.ts averages the observed and FEMA halves). */
47	const HALF_BLEND_PERCENT = 50;
48	
49	/**
50	 * Fixed facts of the METHOD that answers may always quote (they come from the
51	 * system prompt, not from a tool) — all derived from config, never retyped:
52	 * the 0–100 scale, level cut-offs, formula weights, hazard weights, the 50/50
53	 * blend, the scoring window, and every hazard-day threshold in both unit systems.
54	 */
55	export const ALWAYS_KNOWN_NUMBERS: readonly number[] = [
56	  0,
57	  100,
58	  RISK_LEVEL_CUTOFFS.mediumFrom - 1,
59	  RISK_LEVEL_CUTOFFS.mediumFrom,
60	  RISK_LEVEL_CUTOFFS.highFrom - 1,
61	  RISK_LEVEL_CUTOFFS.highFrom,
62	  OVERALL_MIX.weightedAverage,
63	  OVERALL_MIX.worstHazard,
64	  OVERALL_MIX.weightedAverage * 100,
65	  OVERALL_MIX.worstHazard * 100,
66	  ...Object.values(HAZARD_WEIGHTS).flatMap((w) => [w, w * 100]),
67	  HALF_BLEND_PERCENT,
68	  SCORING_WINDOW_DAYS,
69	  Math.round(SCORING_WINDOW_DAYS / 365.25),
70	  ...collectNumbers(Object.values(DAY_METRICS).map((m) => m.threshold)),
71	];
72	
73	/**
74	 * True when `claimed` matches a tool number, allowing display rounding
75	 * (72.43 may be quoted as 72.4 or 72).
76	 * @param claimed - number the answer uses.
77	 * @param known - numbers from tool results.
78	 * @returns whether it traces back to a tool.
79	 */
80	export function matchesKnownNumber(claimed: number, known: readonly number[]): boolean {
81	  return known.some(
82	    (n) => Math.abs(n - claimed) <= 0.051 || Math.round(n) === claimed || Math.abs(Math.round(n * 10) / 10 - claimed) < 1e-9,
83	  );
84	}
85	
86	/** True when a value has the fields every tool output carries. */
87	function isToolOutput(value: unknown): value is ToolOutputBase {
88	  const v = value as Partial<ToolOutputBase> | null;
89	  return !!v && typeof v === "object" && Array.isArray(v.hubIds) && Array.isArray(v.caveats) && "confidence" in v;
90	}
91	
92	/**
93	 * Extracts our tool outputs from earlier conversation turns (role "tool" messages).
94	 * @param messages - conversation history.
95	 * @returns the tool outputs found, oldest first.
96	 */
97	export function toolOutputsFromHistory(messages: readonly ModelMessage[]): ToolOutputBase[] {
98	  const outputs: ToolOutputBase[] = [];
99	  for (const message of messages) {
100	    if (message.role !== "tool" || !Array.isArray(message.content)) continue;
101	    for (const part of message.content) {
102	      if (part.type !== "tool-result") continue;
103	      const value = part.output.type === "json" ? part.output.value : null;
104	      if (isToolOutput(value)) outputs.push(value);
105	    }
106	  }
107	  return outputs;
108	}
109	
110	/**
111	 * Ground truth of one agent turn: this turn's tool results, plus tool results
112	 * from earlier turns of the same conversation (D25 — follow-ups may reuse them).
113	 */
114	export class ToolLedger {
115	  readonly calls: ToolCallRecord[] = [];
116	  private readonly outputs: ToolOutputBase[] = [];
117	  private historyOutputs: ToolOutputBase[] = [];
118	  private extraKnown: number[] = [];
119	  private readonly claimed = new Set<string>();
120	
121	  /**
122	   * Claims a tool call when it STARTS (so parallel duplicates in one step are caught too).
123	   * @param tool - tool name.
124	   * @param input - tool input.
125	   * @returns true the first time this exact call is seen in this answer, false for repeats.
126	   */
127	  claim(tool: string, input: unknown): boolean {
128	    const key = `${tool}:${JSON.stringify(input)}`;
129	    if (this.claimed.has(key)) return false;
130	    this.claimed.add(key);
131	    return true;
132	  }
133	
134	  /**
135	   * Adds facts known for this turn that aren't tool results (e.g. the live hub count from the prompt).
136	   * @param numbers - the numbers.
137	   */
138	  addKnownNumbers(numbers: number[]): void {
139	    this.extraKnown.push(...numbers);
140	  }
141	
142	  /**
143	   * Adds tool results from earlier turns. They count as known hubs and numbers;
144	   * their confidence and caveats are used only when this turn calls no tools.
145	   * @param messages - conversation history.
146	   */
147	  seedFromHistory(messages: readonly ModelMessage[]): void {
148	    this.historyOutputs = toolOutputsFromHistory(messages);
149	  }
150	
151	  /** Current-turn outputs if any, otherwise the earlier ones (for confidence/caveats). */
152	  private relevantOutputs(): ToolOutputBase[] {
153	    return this.outputs.length > 0 ? this.outputs : this.historyOutputs;
154	  }
155	
156	  /**
157	   * Records a tool call and its output.
158	   * @param tool - tool name.
159	   * @param input - validated tool input.
160	   * @param output - the tool's output.
161	   */
162	  record(tool: string, input: unknown, output: ToolOutputBase): void {
163	    this.calls.push({ tool, input, output });
164	    this.outputs.push(output);
165	  }
166	
167	  /** @returns every hub id any tool returned data for (this turn or earlier). */
168	  hubIds(): Set<string> {
169	    return new Set([...this.outputs, ...this.historyOutputs].flatMap((o) => o.hubIds));
170	  }
171	
172	  /** @returns every number found in tool outputs (this turn or earlier), plus the fixed scale bounds. */
173	  numbers(): number[] {
174	    return collectNumbers([...this.outputs, ...this.historyOutputs], [...ALWAYS_KNOWN_NUMBERS, ...this.extraKnown]);
175	  }
176	
177	  /** @returns the confidences of the relevant results that have one. */
178	  confidences(): Confidence[] {
179	    return this.relevantOutputs()
180	      .map((o) => o.confidence)
181	      .filter((c): c is Confidence => c !== null);
182	  }
183	
184	  /** @returns the relevant standing caveats, de-duplicated, in first-seen order. */
185	  caveats(): string[] {
186	    return [...new Set(this.relevantOutputs().flatMap((o) => o.caveats))];
187	  }
188	}
