67	  if (!snapshots || !weatherBounds) {
68	    throw new BoundaryError({
69	      name: "NoDataError",
70	      message: "No scores or weather data yet — run `npm run ingest` first",
71	      functionName: "loadAgentContext",
72	      boundary: "database",
73	    });
