126	/** The visible answer text of a stored assistant message (structured JSON or plain text). */
127	function answerText(content: unknown): string | null {
128	  const text = typeof content === "string" ? content : Array.isArray(content) ? content.map((p) => (p?.type === "text" ? p.text : "")).join("") : "";
129	  if (!text.trim()) return null;
130	  try {
131	    const parsed = JSON.parse(text) as { answer?: unknown };
132	    if (typeof parsed.answer === "string") return parsed.answer;
133	  } catch {
134	    // not JSON: a plain-text answer (e.g. a guard decline)
135	  }
136	  return text;
137	}
