146	export function recentTurnsFromHistory(history: readonly ModelMessage[], turns: number = GUARD_CONFIG.historyTurns): GuardTurn[] {
147	  const result: GuardTurn[] = [];
148	  for (const message of history) {
149	    if (message.role === "user" && typeof message.content === "string" && !message.content.startsWith(RETRY_FEEDBACK_PREFIX)) {
150	      result.push({ question: message.content, answer: "" });
151	    } else if (message.role === "assistant" && result.length > 0) {
152	      const text = answerText(message.content);
153	      if (text) result[result.length - 1].answer = text.slice(0, GUARD_CONFIG.maxAnswerChars);
154	    }
155	  }
156	  return result.slice(-turns);
