190	 * @returns the guard function.
191	 */
192	export function createGuard(source: EnvSource = process.env): (input: GuardInput) => Promise<GuardVerdict> {
193	  let env: { apiKey: string; model: string } | null = null;
194	  let configError = "";
195	  try {
196	    const parsed = getJevEnv(source);
197	    env = { apiKey: parsed.OPENROUTER_API_KEY, model: parsed.JEV_MODEL };
198	  } catch (error) {
199	    configError = describeUnknownError(error);
200	  }
201	  return async (input) => {
202	    if (env) return runGuard(input, env);
203	    console.error(formatBoundaryMessage({ name: "GuardNotConfiguredError", message: `Letting the message through: ${configError}`, functionName: "createGuard", boundary: "config" }));
204	    return {
205	      decision: "allow",
206	      reason: null,
207	      mode: input.history.length > 0 ? "follow_up" : "first",
208	      scores: null,
209	      failedOpen: true,
210	      error: configError,
211	      ms: 0,
212	      model: "not-configured",
213	    };
214	  };
215	}
216	
217	/** What the guard needs to call Jev (injectable for tests). */
218	export interface GuardDeps {
219	  apiKey: string;
220	  model: string;
221	  fetch?: typeof fetch;
222	}
223	
224	/**
225	 * Asks Jev and decides. Never throws: any failure lets the message through (fail open)
226	 * and is logged in the 🐍 format.
227	 * @param input - message, earlier turns, hub names.
228	 * @param deps - API key, model, fetch.
229	 * @returns the verdict.
230	 */
231	export async function runGuard(input: GuardInput, deps: GuardDeps): Promise<GuardVerdict> {
232	  const started = Date.now();
233	  const mode = input.history.length > 0 ? "follow_up" : "first";
234	  try {
235	    const response = await (deps.fetch ?? fetch)(DECISIONS_URL, {
236	      method: "POST",
237	      headers: { Authorization: `Bearer ${deps.apiKey}`, "Content-Type": "application/json" },
238	      body: JSON.stringify(buildDecisionRequest(input, deps.model)),
239	      signal: AbortSignal.timeout(GUARD_CONFIG.timeoutMs),
240	    });
241	    const body = (await response.json()) as { answers?: Record<string, { noul?: unknown }>; error?: { message?: string } };
242	    const inScope = body.answers?.inScope?.noul;
243	    const manipulation = body.answers?.manipulation?.noul;
244	    if (!response.ok || typeof inScope !== "number" || typeof manipulation !== "number") {
245	      throw new Error(`HTTP ${response.status}: ${body.error?.message ?? "no probabilities in the response"}`);
246	    }
247	    const scores = { inScope, manipulation };
248	    return { ...decideFromScores(scores), mode, scores, failedOpen: false, ms: Date.now() - started, model: deps.model };
249	  } catch (error) {
250	    const message = describeUnknownError(error);
251	    console.error(
252	      formatBoundaryMessage({ name: "GuardUnavailableError", message: `Letting the message through: ${message}`, functionName: "runGuard", boundary: "jev" }),
253	    );
254	    return { decision: "allow", reason: null, mode, scores: null, failedOpen: true, error: message, ms: Date.now() - started, model: deps.model };
255	  }
256	}
