36	/**
37	 * Starts a run (if the limits allow) and streams its progress.
38	 * @returns an NDJSON stream, or a friendly JSON error before it starts.
39	 */
40	export async function POST(): Promise<Response> {
41	  try {
42	    const now = new Date();
43	    const before = await readRunEvents({ listEvents: (query) => listEvents(query) }, now);
44	    const status = decideEvalGate(before.starts, before.finishes, now);
45	    if (!status.allowed) return refusal(status);
46	
47	    // Build everything that can fail on config before claiming the slot. (No stray-abort guard here:
48	    // it exits the process, and Next.js already logs stray rejections itself, D108.)
49	    const deps = createAnswerQuestionDeps();
50	    let judge: ReturnType<typeof createJudgeModel> | null = null;
51	    try {
52	      judge = createJudgeModel();
53	    } catch (error) {
54	      console.warn(formatBoundaryMessage({ name: "JudgeUnavailable", message: describeUnknownError(error), functionName: "POST /api/evals/run", boundary: "apiRoute" }));
55	    }
56	    const context = await deps.loadContext({ today: deps.today(), units: "us" });
57	
58	    const runId = randomUUID();
59	    const claimed = await recordEvent({ eventType: EVAL_UI_STARTED, source: "eval", level: "info", correlationId: runId, message: "Eval run started from the app", payload: { model: deps.agentModel.modelId } });
60	    if (!claimed) return errorResponse(userError("internal_error")); // can't count it, so don't run it
61	    const after = await readRunEvents({ listEvents: (query) => listEvents(query) }, new Date());
62	    if (!wonRunSlot(after.starts, after.finishes, runId, new Date())) {
63	      await recordEvent({ eventType: EVAL_FINISHED, source: "eval", level: "info", correlationId: runId, message: "Eval run skipped: another run started at the same moment", payload: { summary: null } });
64	      return refusal({ ...status, allowed: false, reason: "running", running: true });
65	    }
66	
67	    const encoder = new TextEncoder();
68	    const stream = new ReadableStream<Uint8Array>({
69	      async start(controller) {
70	        let open = true;
71	        const send = (event: SuiteEvent | { type: "error"; message: string }) => {
72	          if (!open) return;
73	          try {
74	            controller.enqueue(encoder.encode(`${JSON.stringify(event)}\n`));
75	          } catch {
76	            open = false; // the browser left; keep running so the result is still saved
77	          }
78	        };
79	        try {
80	          const { summary } = await runEvalSuite({ agent: deps.agentModel, context, judge, onEvent: send });
81	          const failed = summary.cases.filter((c) => !c.pass).map((c) => c.caseId);
82	          await recordEvent({
83	            eventType: EVAL_FINISHED,
84	            source: "eval",
85	            level: failed.length ? "warn" : "info",
86	            correlationId: runId,
87	            message: `${summary.passed}/${summary.total} runs passed on ${summary.model} (from the app)`,
88	            payload: { label: summary.model, repeat: 1, failedCases: failed, judge: summary.judge, summary: summary as unknown as Json },
89	          });
90	        } catch (error) {
91	          console.error(formatBoundaryMessage({ name: error instanceof Error ? error.name : "UnknownError", message: describeUnknownError(error), functionName: "POST /api/evals/run", boundary: "apiRoute" }));
92	          await recordEvent({ eventType: EVAL_FINISHED, source: "eval", level: "error", correlationId: runId, message: "Eval run from the app failed", payload: { summary: null } });
93	          send({ type: "error", message: "The eval run stopped before it finished. Please try again later." });
94	        } finally {
95	          if (open) controller.close();
96	        }
97	      },
98	    });
99	    return new Response(stream, { headers: { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store" } });
100	  } catch (error) {
101	    return failure(error, "POST /api/evals/run");
102	  }
103	}
