1	/**
2	 * @module core/api/evalGate
3	 *
4	 * Limits for running the evals from the app (Step 16, D130). The site is public and a run costs
5	 * money (about $0.20) and minutes, so: at most one run every 30 minutes and 4 per UTC day, for
6	 * everyone together, and never two at once. Counted from `eval.ui_started` events (no new table);
7	 * a run counts as in progress until its `eval.finished` event (same correlation id) appears.
8	 * Pure decision logic plus the counting; the route does the rest.
9	 */
10	import type { StoredEvent } from "../db/eventsRepository";
11	
12	/** The limits: the single source of truth. */
13	export const EVAL_RUN_LIMITS = {
14	  minutesBetweenRuns: 30,
15	  runsPerDay: 4,
16	  /** A start without a finish older than this is treated as abandoned (a run takes ~1–3 min). */
17	  runningWindowMinutes: 10,
18	} as const;
19	
20	/** Event recorded when a run starts from the app. */
21	export const EVAL_UI_STARTED = "eval.ui_started";
22	
23	/** Event recorded when any run finishes (app or CLI). */
24	export const EVAL_FINISHED = "eval.finished";
25	
26	/** Whether a run may start now, and if not, why and when. */
27	export interface EvalGateStatus {
28	  allowed: boolean;
29	  reason: "running" | "too_soon" | "daily_limit" | null;
30	  /** When the next run can start (ISO), or null when it can start now (or a run is in progress). */
31	  nextAvailableAt: string | null;
32	  runsLeftToday: number;
33	  running: boolean;
34	}
35	
36	/**
37	 * Decides from today's starts and the recent finishes.
38	 * @param starts - today's `eval.ui_started` events, newest first.
39	 * @param finishes - `eval.finished` events of the last few minutes.
40	 * @param now - the current time.
41	 * @returns the status.
42	 */
43	export function decideEvalGate(starts: readonly StoredEvent[], finishes: readonly StoredEvent[], now: Date): EvalGateStatus {
44	  const minutesAgo = (iso: string) => (now.getTime() - new Date(iso).getTime()) / 60_000;
45	  const finished = new Set(finishes.map((f) => f.correlationId));
46	  const running = starts.some((s) => minutesAgo(s.createdAt) < EVAL_RUN_LIMITS.runningWindowMinutes && !finished.has(s.correlationId));
47	  const runsLeftToday = Math.max(0, EVAL_RUN_LIMITS.runsPerDay - starts.length);
48	  if (running) return { allowed: false, reason: "running", nextAvailableAt: null, runsLeftToday, running };
49	  if (runsLeftToday === 0) {
50	    const tomorrow = new Date(now);
51	    tomorrow.setUTCHours(24, 0, 0, 0);
52	    return { allowed: false, reason: "daily_limit", nextAvailableAt: tomorrow.toISOString(), runsLeftToday, running };
53	  }
54	  const last = starts[0];
55	  if (last && minutesAgo(last.createdAt) < EVAL_RUN_LIMITS.minutesBetweenRuns) {
56	    const next = new Date(new Date(last.createdAt).getTime() + EVAL_RUN_LIMITS.minutesBetweenRuns * 60_000);
57	    return { allowed: false, reason: "too_soon", nextAvailableAt: next.toISOString(), runsLeftToday, running };
58	  }
59	  return { allowed: true, reason: null, nextAvailableAt: null, runsLeftToday, running };
60	}
61	
62	/**
63	 * After recording its own start, a run checks it is the only one in progress (two clicks at the
64	 * same moment can both pass the gate). The earliest start wins; ties go to the smaller id.
65	 * @param starts - today's `eval.ui_started` events (including this run's).
66	 * @param finishes - recent `eval.finished` events.
67	 * @param runId - this run's correlation id.
68	 * @param now - the current time.
69	 * @returns true when this run should go ahead.
70	 */
71	export function wonRunSlot(starts: readonly StoredEvent[], finishes: readonly StoredEvent[], runId: string, now: Date): boolean {
72	  const finished = new Set(finishes.map((f) => f.correlationId));
73	  const windowMs = EVAL_RUN_LIMITS.runningWindowMinutes * 60_000;
74	  const running = starts
75	    .filter((s) => s.correlationId === runId || (now.getTime() - new Date(s.createdAt).getTime() < windowMs && !finished.has(s.correlationId)))
76	    .sort((a, b) => a.createdAt.localeCompare(b.createdAt) || String(a.correlationId).localeCompare(String(b.correlationId)));
77	  return running[0]?.correlationId === runId;
78	}
79	
80	/** What the gate reads (injectable for tests). */
81	export interface EvalGateDeps {
82	  listEvents: (query: { eventType: string; since: string; limit: number }) => Promise<StoredEvent[]>;
83	  now: () => Date;
84	}
85	
86	/**
87	 * Reads today's starts and recent finishes, then decides.
88	 * @param deps - event reader and clock.
89	 * @returns the status.
90	 */
91	export async function evalGateStatus(deps: EvalGateDeps): Promise<EvalGateStatus> {
92	  const now = deps.now();
93	  const { starts, finishes } = await readRunEvents(deps, now);
94	  return decideEvalGate(starts, finishes, now);
95	}
96	
97	/**
98	 * Reads today's starts and the recent finishes.
99	 * @param deps - event reader.
100	 * @param now - the current time.
101	 * @returns both lists, newest first.
102	 */
103	export async function readRunEvents(deps: Pick<EvalGateDeps, "listEvents">, now: Date): Promise<{ starts: StoredEvent[]; finishes: StoredEvent[] }> {
104	  const startOfDay = `${now.toISOString().slice(0, 10)}T00:00:00.000Z`;
105	  const recent = new Date(now.getTime() - EVAL_RUN_LIMITS.runningWindowMinutes * 60_000).toISOString();
106	  const [starts, finishes] = await Promise.all([
107	    deps.listEvents({ eventType: EVAL_UI_STARTED, since: startOfDay, limit: 20 }),
108	    deps.listEvents({ eventType: EVAL_FINISHED, since: recent, limit: 20 }),
109	  ]);
110	  return { starts, finishes };
111	}
